fn chat_text(chat: &Chat) -> String {
    let mut out = format!("{}\nChat: {}\n", chat.title, chat.id);
    for message in &chat.messages {
        out.push_str(&format!(
            "\n{}\n{}\n",
            if message.role == "user" {
                "You"
            } else if message.sender.is_empty() {
                "Assistant"
            } else {
                &message.sender
            },
            message.content
        ));
    }
    out
}
