async fn handoff_idle_list_scope(personal: bool) -> R<()> {
    tokio::time::timeout(Duration::from_secs(15), async {
        let (peer, mut client, store, _directory, _suite) = fixture().await?;
        peer.get("/__test/control?action=no-recovery")?;
