    Rust,
    Npm,
    Pip,
    Cli,
}
impl ClientIdentity {
    pub(crate) fn header(self) -> &'static str {
        match self {
            Self::Rust => "rust",
            Self::Npm => "npm",
            Self::Pip => "pip",
            Self::Cli => "cli",
        }
    }
